  ["roofMain", () => V.roofMain(g)],
  ["roofWing", () => V.roofWing(g)],
  ["ovenVault", () => V.ovenVault(g)],
  ["chimneyStack", () => V.chimneyStack(g)],
  ["woodpile", () => V.woodpile(g, 7, 10, 24, 25)],
