import { join } from "node:path";

export const MCD = "/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs";

// ---- palette (palette.json ids only) ------------------------------------------------------------------------------------
export const DEEPSLATE_BRICKS = "deepslate_bricks";
