import { tmpdir } from "node:os";
import { join } from "node:path";

const MCD = "/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs";

// ---- palette (palette.json ids only) ------------------------------------------------------------------------------------
