// ---- site (plan.md SITE; all ranges inclusive) -----------------------------------------------------------------------
export const LOT = { x0: 0, x1: 23, z0: 0, z1: 31, height: 24 };
export const GROUND_Y = 0;
export const WALK_Y = 1;
